        return len(self.iterable)

    if hasattr(self.iterable, 'shape') and isinstance(self.iterable.shape, (list, tuple)):
        return self.iterable.shape[0]

    if hasattr(self.iterable, '__len__'):
        return len(self.iterable)

    return self.total if hasattr(self, 'total') else 0
